// MT2009_PLUS_SUPERSTONE_V1 (helpers): event Super Kamieni (the owner, 29 October 2026).
// While the event flag superstone_event is 1..4, every Metin stone SpawnMob puts down on a
// world map (index < 10000: never a dungeon or another instance) gets that many extra
// stones of its race on the same spot, each with its own rotation. The extras are
// independent: no regen of their own (the stone the regen put down is the one SpawnMob
// returns, and only it is SetRegen'd, so the regen's count is untouched), they drop and
// give experience like any stone and simply die. What keeps them from piling up when the
// regen respawns a stone whose extras were left standing: per map and race the extras
// alive are at most (the flag) times the stones alive they were put beside - a respawned
// stone gets only the extras still missing. The flag going to 0 takes away the extras
// nobody has hit yet (SuperStoneEventOff, from CQuestManager::SetEventFlag).
namespace
{
	struct TSuperStoneGroup
	{
		std::vector<DWORD> parents;	// the stones the extras were put beside (VIDs)
		std::vector<DWORD> extras;	// the extras (VIDs)
	};
	std::map<std::pair<long, DWORD>, TSuperStoneGroup> s_mapSuperStoneGroups;

	void SuperStonePrune(std::vector<DWORD>& vids)
	{
		std::vector<DWORD> alive;
		alive.reserve(vids.size());
		for (size_t i = 0; i < vids.size(); ++i)
		{
			LPCHARACTER ch = CHARACTER_MANAGER::instance().Find(vids[i]);
			if (ch && !ch->IsDead())
				alive.push_back(vids[i]);
		}
		vids.swap(alive);
	}

	void SpawnExtraStones(LPCHARACTER pkParent, const CMob* pkMob, long lMapIndex, long x, long y, long z, bool bSpawnMotion)
	{
		const int iFlag = quest::CQuestManager::instance().GetEventFlag("superstone_event");
		if (iFlag <= 0 || !pkParent || !pkMob)
			return;
		const int iPerStone = MIN(iFlag, 4);
		TSuperStoneGroup& group = s_mapSuperStoneGroups[std::make_pair(lMapIndex, (DWORD)pkMob->m_table.dwVnum)];
		SuperStonePrune(group.parents);
		SuperStonePrune(group.extras);
		group.parents.push_back((DWORD)pkParent->GetVID());
		const int iCount = MIN(iPerStone, (int)group.parents.size() * iPerStone - (int)group.extras.size());
		int iSpawned = 0;
		for (int i = 0; i < iCount; ++i)
		{
			LPCHARACTER ch = CHARACTER_MANAGER::instance().CreateCharacter(pkMob->m_table.szLocaleName);
			if (!ch)
				break;
			ch->SetProto(pkMob);
			ch->SetRotation(number(0, 360));
			if (!ch->Show(lMapIndex, x, y, z, bSpawnMotion))
			{
				M2_DESTROY_CHARACTER(ch);
				break;
			}
			group.extras.push_back((DWORD)ch->GetVID());
			++iSpawned;
		}
		if (iSpawned > 0)
			sys_log(0, "SUPERSTONE: %u map %ld at %ld %ld: %d extra stone(s) (flag %d, %u alive beside %u)",
					(DWORD)pkMob->m_table.dwVnum, lMapIndex, x, y, iSpawned, iFlag,
					(unsigned int)group.extras.size(), (unsigned int)group.parents.size());
	}
}

// MT2009_PLUS_SUPERSTONE_V1 (off): the event is over - the extras still at full health go,
// the ones being fought stay and die as usual.
void SuperStoneEventOff()
{
	int iRemoved = 0;
	for (std::map<std::pair<long, DWORD>, TSuperStoneGroup>::iterator it = s_mapSuperStoneGroups.begin();
			it != s_mapSuperStoneGroups.end(); ++it)
	{
		std::vector<DWORD> kept;
		for (size_t i = 0; i < it->second.extras.size(); ++i)
		{
			LPCHARACTER ch = CHARACTER_MANAGER::instance().Find(it->second.extras[i]);
			if (!ch || ch->IsDead())
				continue;
			if (ch->GetHP() >= ch->GetMaxHP())
			{
				M2_DESTROY_CHARACTER(ch);
				++iRemoved;
				continue;
			}
			kept.push_back(it->second.extras[i]);
		}
		it->second.extras.swap(kept);
	}
	if (iRemoved > 0)
		sys_log(0, "SUPERSTONE: event off, %d untouched extra stone(s) removed", iRemoved);
}
#endif

